style.css:
/* غيّر الدومين حسب الموقع اللي فيه زرار Play */
@-moz-document domain("roblox.com") {
/* 1) خليه أحمر دائمًا */
  /* استبدل .PLAY_SELECTOR بالمحدِّد الحقيقي لزرار Play */
  .PLAY_SELECTOR {
    background: red !important;
    border-color: red !important;
    color: #fff !important;
  }

  /* 2) أحمر فقط أثناء الضغط (لحظة الكليك) */
  .PLAY_SELECTOR:active {
    background: red !important;
    border-color: red !important;
    color: #fff !important;
  }

  /* 3) يفضل أحمر بعد الضغط (طالما عليه focus) */
  .PLAY_SELECTOR:focus {
    background: red !important;
    border-color: red !important;
    color: #fff !important;
    outline: none !important; /* اختياري */
  }
}
